-- public.frame_says(p_world uuid, p_x integer, p_y integer)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.frame_says(p_world uuid, p_x integer, p_y integer)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare v_out text := ''; j building; v_f floor_tile; v_cols text;
begin
  -- The jetty or balcony over it, if any, on its lowest storey.
  select * into j from building where world_id = p_world and id = frame_jetty_of(p_world, p_x, p_y);
  if j.id is not null then
    select * into v_f from floor_tile ft
     where ft.world_id = p_world and ft.x = p_x and ft.y = p_y and ft.level between 1 and j.levels and ft.building = j.id
     order by ft.level limit 1;
    if v_f.world_id is not null then
      if v_f.kind = 'stairs' then
        -- A spiral one is climbed from any side.
        v_out := v_out || case when bill_done(v_f.needed) and v_f.hand = 's'
          then ' Outside spiral staircase: up to ' || j.name || ' storey ' || (v_f.level + 1) || ', climbed from any side.'
          when bill_done(v_f.needed)
          then ' Outside staircase: up to ' || j.name || ' storey ' || (v_f.level + 1)
            || ', climbed from the ' || side_name(coalesce(v_f.facing, 's')) || '.'
          else ' Outside ' || case when v_f.hand = 's' then 'spiral staircase' else 'staircase' end
            || ' planned: up to ' || j.name || ' storey ' || (v_f.level + 1) || '.' end;
      elsif not bill_done(v_f.needed) then
        v_out := v_out || ' Jetty planned over it: ' || j.name || ' storey ' || (v_f.level + 1) || '.';
      elsif exists (select 1 from frame_storey(p_world, j.id, v_f.level) s where s.x = p_x and s.y = p_y) then
        v_out := v_out || ' Jetty over it: ' || j.name || ' storey ' || (v_f.level + 1)
          || ', part of that storey. Open sides need a wall, railing or columns to enclose it; a roof over it needs walls or columns, not railings.';
      else
        v_out := v_out || ' Balcony over it: ' || j.name || ' storey ' || (v_f.level + 1)
          || ', walled off from the storey. Railing only, no roof.';
      end if;
    end if;
  end if;
  -- The columns on its corners, storey by storey.
  select string_agg(lower(m.name) || ' on the ' || side_name(case when c.y = p_y then 'n' else 's' end) || '-'
           || side_name(case when c.x = p_x then 'w' else 'e' end) || ' corner'
           || case when c.level > 0 then ' of storey ' || (c.level + 1) else '' end
           || case when bill_done(c.needed) then '' else ' (needs ' || bill_text(c.material, c.needed) || ')' end,
         '; ' order by c.level, c.y, c.x)
    into v_cols
    from building_column c join build_material_def m on m.id = c.material
   where c.world_id = p_world and c.x in (p_x, p_x + 1) and c.y in (p_y, p_y + 1);
  if v_cols is not null then v_out := v_out || ' Columns: ' || v_cols || '.'; end if;
  -- A roof on columns: shelter for what lies there, and not a room.
  if sheltered(p_world, 0, p_x, p_y) and not indoors(p_world, 0, p_x, p_y) then
    v_out := v_out || ' Under a roof on columns: decay ×' || indoors_decay()
      || '. Beds here count as outdoors (indoor rest ×' || indoors_rest()
      || ' needs walls all round).';
  end if;
  return v_out;
end $function$
